Análise do problema:

**Refeições:** multiplicam tudo por `P' = ∏a'_i` independentemente da ordem, e o termo aditivo `S(σ)=Σ b'_{σ(i)}·∏_{j>i}a'_{σ(j)}` é maximizado ordenando as refeições por `b'/(a'−1)` decrescente (argumento de troca adjacente).

**Feitiços:** o chave é que o valor após K aplicações é no máximo `f^K(x)` com `f(z)=max_i(a_i·z+b_i)` (cota superior por indução, pois f é crescente), e o guloso miópico atinge exatamente `f^K(x)`. Como `f` é envelope superior de retas, todos os breakpoints são ≤ 10⁹; então basta simular `f` exatamente (valores cabem em long) enquanto `v ≤ B*` (cruzamento máximo com a reta de maior coeficiente angular), e depois usar forma fechada com essa reta: `a^m·v + b·(a^m−1)/(a−1)`, tudo módulo 10⁹+7. Assim a maximização é feita sobre os valores reais, sem precisar de big integers. Resposta final: `P'·f^K(x) + S_max (mod 1e9+7)`.

Validei contra todos os exemplos fornecidos (185; 1/100/200000001/200000002; 1611/3123/15120099/4635; 707385849...; exemplos 5).

```java
import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 1000000007L;
    static byte[] buf;
    static int pos = 0;

    private static long nextLong() {
        while (pos < buf.length && (buf[pos] < '0' || buf[pos] > '9')) pos++;
        if (pos >= buf.length) return -1;
        long v = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') v = v * 10 + (buf[pos++] - '0');
        return v;
    }

    private static long modpow(long b, long e) {
        long r = 1; b %= MOD;
        while (e > 0) {
            if ((e & 1) == 1) r = r * b % MOD;
            b = b * b % MOD;
            e >>= 1;
        }
        return r;
    }

    public static void main(String[] args) throws IOException {
        ByteArrayOutputStream bos = new ByteArrayOutputStream(1 << 23);
        byte[] chunk = new byte[1 << 16];
        int r;
        while ((r = System.in.read(chunk)) > 0) bos.write(chunk, 0, r);
        buf = bos.toByteArray();

        int n = (int) nextLong(), m = (int) nextLong();
        long K = nextLong();
        int[] A = new int[n], B = new int[n];
        for (int i = 0; i < n; i++) A[i] = (int) nextLong();
        for (int i = 0; i < n; i++) B[i] = (int) nextLong();
        int[] MA = new int[m], MB = new int[m];
        for (int i = 0; i < m; i++) MA[i] = (int) nextLong();
        for (int i = 0; i < m; i++) MB[i] = (int) nextLong();
        int Q = (int) nextLong();
        int[] X = new int[Q];
        for (int i = 0; i < Q; i++) X[i] = (int) nextLong();

        long P = 1L;
        Integer[] midx = new Integer[m];
        final int[] ma = MA, mb = MB;
        for (int i = 0; i < m; i++) { midx[i] = i; P = P * ma[i] % MOD; }
        Arrays.sort(midx, (i, j) -> {
            long ci = (long) mb[i] * (ma[j] - 1L);
            long cj = (long) mb[j] * (ma[i] - 1L);
            return ci != cj ? (ci > cj ? -1 : 1) : 0;
        });
        long S = 0, suff = 1;
        for (int i = m - 1; i >= 0; i--) {
            int t = midx[i];
            S = (S + (long) mb[t] * suff) % MOD;
            suff = suff * ma[t] % MOD;
        }

        boolean allOne = true;
        for (int i = 0; i < n; i++) if (A[i] != 1) { allOne = false; break; }
        long bmax = 0;
        for (int i = 0; i < n; i++) if (B[i] > bmax) bmax = B[i];

        long aTop = 2, bTop = 0, Bt = 0, invA = 1;
        long[] sA = new long[]{0}, sB = new long[]{0};
        int[] bpc = new int[1];
        int ss = 1, bc = 0;

        if (!allOne) {
            int ti = 0;
            for (int i = 1; i < n; i++) if (A[i] > A[ti] || (A[i] == A[ti] && B[i] > B[ti])) ti = i;
            aTop = A[ti]; bTop = B[ti];
            for (int i = 0; i < n; i++) {
                if (A[i] < aTop && B[i] > bTop) {
                    long zf = (long) (B[i] - bTop) / (aTop - A[i]);
                    if (zf > Bt) Bt = zf;
                }
            }
            invA = modpow(aTop - 1, MOD - 2);
            long[] keys = new long[n];
            for (int i = 0; i < n; i++) keys[i] = ((long) A[i] << 31) | (long) B[i];
            Arrays.sort(keys);
            sA = new long[n]; sB = new long[n];
            int top = 0;
            for (int k = 0; k < n; k++) {
                long a = keys[k] >>> 31, b = keys[k] & ((1L << 31) - 1L);
                while (top > 0 && sA[top - 1] == a) top--;
                while (top >= 2) {
                    long a1 = sA[top - 1], b1 = sB[top - 1];
                    long a2 = sA[top - 2], b2 = sB[top - 2];
                    if ((b1 - b) * (a1 - a2) <= (b2 - b1) * (a - a1)) top--;
                    else break;
                }
                sA[top] = a; sB[top] = b; top++;
            }
            ss = top; bc = top - 1;
            bpc = new int[bc > 0 ? bc : 1];
            for (int j = 0; j < bc; j++) {
                long num = sB[j] - sB[j + 1], den = sA[j + 1] - sA[j];
                bpc[j] = (int) (-Math.floorDiv(-num, den));
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int q = 0; q < Q; q++) {
            long x = X[q], sv;
            if (allOne) {
                sv = (x + (K % MOD) * (bmax % MOD)) % MOD;
            } else {
                long v = x, steps = 0;
                while (steps < K && v <= Bt) {
                    int lo = 0, hi = bc;
                    while (lo < hi) {
                        int mid = (lo + hi) >>> 1;
                        if ((long) bpc[mid] <= v) lo = mid + 1; else hi = mid;
                    }
                    int li = lo < ss ? lo : ss - 1;
                    v = sA[li] * v + sB[li];
                    steps++;
                }
                long mRem = K - steps;
                long vm = v % MOD;
                if (mRem == 0) sv = vm;
                else {
                    long am = modpow(aTop, mRem);
                    sv = (am * vm + (bTop % MOD) * ((am - 1 + MOD) % MOD) % MOD * invA) % MOD;
                }
            }
            sb.append((P * sv + S) % MOD).append('\n');
        }
        System.out.print(sb);
    }
}
